def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0.0

    slots = int(supply / WATER_REQ)
    if slots < 0:
        slots = 0

    prev_bids = []
    prev_high = 0.0
    prev_count = 0
    desperate_opp = 0
    rich_opp = 0

    for opp in alive:
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
            desperate_opp += 1
        if opp.get('budget', 0) >= budget:
            rich_opp += 1
        prev = opp.get('previous_trace') or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(bid)
            prev_count += 1
            if bid > prev_high:
                prev_high = bid

    need_urgent = hp <= 2 or no_water >= 1
    need_soon = hp <= 4

    if not alive:
        if need_urgent:
            return float(min(budget, DAILY_SALARY * 0.75))
        return float(min(budget, DAILY_SALARY * 0.25))

    competitors = len(alive) + 1
    shortage = slots < competitors
    severe_shortage = slots <= 1

    if prev_count > 0:
        sorted_bids = sorted(prev_bids, reverse=True)
        top1 = sorted_bids[int(0)]
        top2 = sorted_bids[int(1)] if len(sorted_bids) > 1 else top1
        avg_prev = sum(prev_bids) / float(len(prev_bids))
    else:
        top1 = DAILY_SALARY * 0.75
        top2 = DAILY_SALARY * 0.65
        avg_prev = DAILY_SALARY * 0.6

    if need_urgent:
        target = max(DAILY_SALARY * 0.88, top1 + 1.5)
        if severe_shortage:
            target = max(target, DAILY_SALARY * 0.95)
        return float(min(budget, target))

    if severe_shortage:
        if hp >= 6 and budget < max(120, avg_prev * 2):
            target = DAILY_SALARY * 0.22
        else:
            target = max(DAILY_SALARY * 0.72, top2 + 1.0)
            if desperate_opp >= 2:
                target += 4.0
        return float(min(budget, target))

    if shortage:
        if hp >= 7 and prev_high >= DAILY_SALARY * 0.9:
            target = DAILY_SALARY * 0.2
        else:
            target = max(DAILY_SALARY * 0.48, avg_prev * 0.82)
            if need_soon:
                target = max(target, top2 + 0.5)
            if desperate_opp >= 1:
                target += 2.0
            if rich_opp >= 2 and hp >= 6:
                target -= 3.0
        return float(min(budget, max(0.0, target)))

    target = DAILY_SALARY * 0.24
    if need_soon:
        target = DAILY_SALARY * 0.38
    if prev_count > 0 and avg_prev < DAILY_SALARY * 0.35:
        target = max(target, avg_prev + 1.0)
    return float(min(budget, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    # Gather yesterday's bids from alive opponents
    prev_bids = []
    for opp_id, opp in opponents_status.items():
        if opp['alive']:
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev['bid'])

    # Determine target bid based on my hp and budget
    hp = my_status['hp']
    budget = my_status['budget']

    if prev_bids:
        # Use median to avoid extremes
        sorted_bids = sorted(prev_bids)
        n = len(sorted_bids)
        mid = int(n // 2)
        if n % 2 == 0:
            median = (sorted_bids[mid - 1] + sorted_bids[mid]) / 2.0
        else:
            median = sorted_bids[mid]
        if hp <= 2:
            # Desperate: outbid median by a margin
            target = min(budget, median + 5.0)
        else:
            # Comfortable: bid just above median or slightly below salary
            target = min(budget, max(DAILY_SALARY * 0.5, median + 1.0))
    else:
        # No previous bids, use default
        if hp <= 2:
            target = min(budget, DAILY_SALARY * 0.9)
        else:
            target = min(budget, DAILY_SALARY * 0.6)

    # Ensure at least minimum reasonable bid
    min_bid = max(DAILY_SALARY * 0.2, target * 0.5) if target > 0 else DAILY_SALARY * 0.2
    bid = max(min_bid, target)

    return int(bid) if bid == int(bid) else float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80

    # Alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    # If no opponents, bid conservatively
    if not alive_opps:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Extract yesterday bids from previous_trace
    yesterday_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    supply = float(day_context['supply'])

    # Estimate how many water units are likely needed to avoid a no-water day.
    # If supply is scarce relative to WATER_REQ, competition increases.
    # Use a simple urgency score.
    urgency = 0.0
    if supply < WATER_REQ:
        urgency = 1.0
    else:
        # supply in [15,25], WATER_REQ=7 => urgency between ~0 and ~0.5
        urgency = max(0.0, min(1.0, (WATER_REQ * 2 - supply) / (WATER_REQ)))

    # Base target bid: slightly over yesterday's competitive max when our hp is not critical.
    # Otherwise, increase bid to prioritize survival.
    if my_status['hp'] <= 2:
        target = DAILY_SALARY * 0.9 + urgency * (DAILY_SALARY * 0.2)
    elif my_status['hp'] <= 4:
        target = DAILY_SALARY * 0.65 + urgency * (DAILY_SALARY * 0.15)
    else:
        # If yesterday had very high bids, we must match/beat.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            target = highest_prev_bid + 3.0 + urgency * 5.0
        else:
            target = max(DAILY_SALARY * 0.55, highest_prev_bid * 0.92 + 2.0) + urgency * 4.0

    # Do not exceed budget
    bid = min(float(my_status['budget']), float(target))

    # Keep bids within a reasonable range relative to salary to avoid waste.
    # (Budget may be lower; min above handles that.)
    upper_soft = DAILY_SALARY * 1.2
    if bid > upper_soft:
        bid = upper_soft

    # Ensure non-negative
    if bid < 0:
        bid = 0.0

    return float(bid)
